        emoji: '⚡',
        body: `▼ゼロから：電気の勉強は「電荷」という小さな粒の話から始まります。物質はすべて原子でできていて、原子の中にはプラスの電気をもつ陽子と、マイナスの電気をもつ電子があります。この電気の量を「電荷」と呼び、単位はクーロン（C）です。金属の中では電子が自由に動き回れるので、電子がいっせいに同じ方向へ流れると「電流」になります。電流を水の流れにたとえるなら、電圧は水を押し出すポンプの圧力、抵抗は水路の細さです。この3つの関係を押さえることが、電気理論すべての土台になります。

━━━━━━━━━━━━━━━━━━━━━━
🔑 電流とは「電荷の流れ」
━━━━━━━━━━━━━━━━━━━━━━
・電流の単位はアンペア（A）。1秒間に1クーロンの電荷が断面を通過するとき、その電流は1Aと定義される。
・式で書くと I＝Q／t（I：電流［A］、Q：電荷［C］、t：時間［s］）。
・★電流の向きは「プラスからマイナスへ」と決められているが、実際に動いている電子は「マイナスからプラスへ」流れる。向きが逆であることは頻出のひっかけ。
・電子1個の電荷は約1.6×10のマイナス19乗クーロン。つまり1Aの電流では、毎秒およそ6.24×10の18乗個もの電子が流れている。
・例題：2秒間に10Cの電荷が流れたときの電流は？
　式：I＝Q／t
　代入：I＝10／2
　答え：5 A

━━━━━━━━━━━━━━━━━━━━━━
🔑 電圧とは「電気を押す力の差」
━━━━━━━━━━━━━━━━━━━━━━
・電圧の単位はボルト（V）。2点間の電位の差なので「電位差」とも呼ぶ。
・水にたとえると、高いタンクと低いタンクの水位差。水位差が大きいほど水は勢いよく流れる→電圧が高いほど電流は流れやすい。
・1Vとは、1Cの電荷を運ぶのに1J（ジュール）の仕事が必要な電位差のこと。V＝W／Q。
・○乾電池は約1.5V、家庭のコンセントは100V、送電線は数万〜数十万V。
・⚠「電圧が流れる」という表現は誤り。流れるのは電流、加わるのが電圧。試験の文章でもこの言葉づかいで正誤を判断させることがある。

━━━━━━━━━━━━━━━━━━━━━━
🔑 導体・絶縁体・半導体
━━━━━━━━━━━━━━━━━━━━━━
・導体：自由電子が多く電流をよく通す。銅・アルミ・銀など。
・絶縁体：自由電子がほとんどなく電流を通さない。ゴム・ガラス・磁器など。
・半導体：導体と絶縁体の中間の性質。シリコン・ゲルマニウムなど。温度が上がると抵抗が下がる（導体は逆に上がる）★。
・→この半導体の性質が、後の章で学ぶダイオードやトランジスタの土台になる。

【図解】単位につく接頭語（必ず換算できるように）
　接頭語｜読み｜大きさ
　G｜ギガ｜10の9乗
　M｜メガ｜10の6乗
　k｜キロ｜10の3乗
　m｜ミリ｜10のマイナス3乗
　μ｜マイクロ｜10のマイナス6乗
　n｜ナノ｜10のマイナス9乗
　p｜ピコ｜10のマイナス12乗
　⚠ 計算問題ではmA→A、μF→Fへの換算ミスが最大の失点源。単位を必ずそろえてから計算する

━━━━━━━━━━━━━━━━━━━━━━
🔑 頻出ひっかけと本試験での問われ方
━━━━━━━━━━━━━━━━━━━━━━
・×「電流の向きと電子の移動方向は同じ」→○逆方向。
・×「導体は温度が上がると抵抗が下がる」→○導体は上がる。下がるのは半導体。
・×「電圧の単位はアンペア」→○ボルト。単純だが焦ると間違える。
・計算問題では、mAやkΩのまま代入させて桁を誤らせる出題が定番。まずSI基本単位（A、V、Ω）に直す習慣をつける。
・電荷と電流の関係式 I＝Q／t は、コンデンサの充放電の問題でも再登場する。

━━━━━━━━━━━━━━━━━━━━━━
🔑 仕上げの一問一答
━━━━━━━━━━━━━━━━━━━━━━
・Q：2秒間に6Cの電荷が流れたときの電流は　→A：I＝Q／t＝6／2＝3A。定義式に代入するだけで解ける
・Q：電子の移動方向と電流の向きの関係は　→A：互いに逆向き。電流はプラスからマイナスと約束されている
・Q：半導体の温度が上がると抵抗はどうなる　→A：下がる。導体は上がる。逆の性質を対で覚える
・Q：0.5mAは何Aか　→A：0.0005A（5×10のマイナス4乗A）。mは1000分の1
・Q：2200pFは何μFか　→A：0.0022μF。pはμの100万分の1。桁換算は指数で処理する
・Q：1.5Vの電池で1Cの電荷を運ぶ仕事は　→A：W＝QV＝1×1.5＝1.5J。V＝W／Qの逆算
・Q：「電圧が流れる」という表現は正しいか　→A：誤り。流れるのは電流で、電圧は加わるもの

★ここだけ暗記
・電流I＝Q／t、電圧V＝W／Q。
・電流の向きはプラス→マイナス、電子はその逆。
・導体は温度上昇で抵抗増、半導体は抵抗減。
・接頭語：k＝1000、m＝1／1000、μ＝100万分の1。換算してから計算。`,
