・×「電話のPCMの標本化周波数は4kHz」→○8kHz（4kHzは信号の最高周波数）。
・数値計算は「2倍する」「2で割る」だけだが、標本化周期Ts＝1／fs（8kHzなら125μs★）を求めさせる変形もある。125μsはPCMフレームの節でも使う重要数値。

