        emoji: '🎼',
        body: `▼ゼロから：高速なデータを1本の搬送波で送ろうとすると、1ビットの時間が極端に短くなり、建物などで反射して遅れて届く電波（マルチパス）と混ざってぐちゃぐちゃになります。そこでOFDMは発想を変え、データを数百〜数千本の「サブキャリア」に小分けして、それぞれをゆっくり並列に送ります。大きな荷物を1台のトラックで飛ばすのではなく、たくさんの自転車でゆっくり分担するイメージです。1つ1つが遅いので反射波の遅れの影響が相対的に小さくなる。地上デジタル放送、Wi-Fi、LTE・5Gがそろって採用した現代無線の大黒柱です。

━━━━━━━━━━━━━━━━━━━━━━
🔑 OFDMのしくみ：直交する多数のサブキャリア
━━━━━━━━━━━━━━━━━━━━━━
・多数のサブキャリアを、互いに「直交」する周波数間隔で密に並べる★。直交とは、あるサブキャリアのピーク位置で他のサブキャリアの成分がゼロになる関係。
・→ガードバンドなしで隣接させても互いに干渉しない○。周波数利用効率が高い。
・各サブキャリアは低速なのでシンボル時間が長い→マルチパスの遅延波がシンボル時間に対して相対的に短くなり、符号間干渉が起きにくい★。
・変調・復調はFFT（高速フーリエ変換）・IFFTの信号処理で一括して行う★。数千本の発振器を並べる必要はない。
・各サブキャリアにはQPSKや64QAMなどを乗せる（OFDMは「乗せ方の枠組み」で、中身の変調は別途選ぶ）。

━━━━━━━━━━━━━━━━━━━━━━
🔑 ガードインターバル：反射波対策の決め手
━━━━━━━━━━━━━━━━━━━━━━
・シンボルの先頭に、シンボル末尾のコピー（サイクリックプレフィックス）を付け足した区間をガードインターバル（GI）という★。
・遅れて届く反射波の遅延がGIの長さ以内なら、前のシンボルが現在のシンボルに食い込まず、符号間干渉を防げる○。
・→OFDMはマルチパス（ゴースト）に強い。地上デジタル放送で建物反射だらけの都市部でも映る理由★。
・さらに同じ周波数で複数の送信所から同じ信号を送るSFN（単一周波数ネットワーク）も、遅延波をGIで吸収できるからこそ成立する★。
・GIを長くするほど反射に強いが、その分だけデータを送らない時間が増え伝送効率は下がる（トレードオフ）。

━━━━━━━━━━━━━━━━━━━━━━
🔑 OFDMの弱点と実際のシステム
━━━━━━━━━━━━━━━━━━━━━━
・弱点1：PAPR（ピーク対平均電力比）が大きい★。多数のサブキャリアの山が偶然そろうと大きなピークが出る。→送信増幅器に直線性が要求され、電力効率が下がる。携帯端末の上りに別方式（SC-FDMA）を使う理由。
・弱点2：周波数オフセット・位相雑音に敏感。サブキャリア間隔が狭いため、わずかな周波数ずれで直交性が崩れる★。
・採用例：地上デジタル放送（ISDB-T）、Wi-Fi（IEEE 802.11a/g/n/ac/ax）、LTE・5Gの下り、電力線通信など。
・例題：サブキャリア1000本、各サブキャリアが64QAM（6ビット）、シンボルレート1kボー（サブキャリアあたり）のときの概算ビットレート
　式：R＝本数×ビット数×シンボルレート
　代入：1000×6×1000
　答え：6 Mbps（GIなどのオーバヘッドで実際はやや低下）

【図解】OFDMの特徴
　項目｜内容｜効果
　多数サブキャリア｜低速並列伝送｜符号間干渉に強い
　直交配置｜ガードバンド不要｜周波数利用効率高い
　ガードインターバル｜末尾のコピーを先頭に｜マルチパス吸収・SFN可能
　FFT処理｜一括変復調｜装置を簡素化
　⚠ 弱点はPAPR大と周波数ずれに敏感。長所だけでなく短所も問われる

━━━━━━━━━━━━━━━━━━━━━━
🔑 頻出ひっかけと本試験での問われ方
━━━━━━━━━━━━━━━━━━━━━━
・×「OFDMはマルチパスに弱い」→○強い。それが最大の採用理由。
・×「サブキャリア間にガードバンドを設けて干渉を防ぐ」→○直交性で防ぐ。ガードバンド不要。
・×「ガードインターバルはシンボルの先頭部分のコピーを末尾に付ける」→○末尾のコピーを先頭に付ける。
・×「OFDMはピーク対平均電力比が小さい」→○大きい。増幅器の直線性が課題。
・地デジ・Wi-Fi・LTEでの採用、SFNが可能な理由（GI）、FFTによる実現は繰り返し出題される。

★ここだけ暗記
・OFDM＝直交サブキャリアで低速並列→マルチパスに強い。
・GI（末尾コピーを先頭に）で遅延波を吸収→SFNも可能。
・実現はIFFT／FFT。中身の変調はQPSK〜QAMを選択。
・弱点：PAPR大・周波数オフセットに敏感。`,
