        id: 'ts-ko-35',
        title: '雑音の種類と熱雑音',
        emoji: '🌫',
        body: `▼ゼロから：ラジオのザーという音、昔のテレビの砂嵐。あれが雑音の姿です。雑音には外から飛び込むもの（雷、モータの火花、他の無線局）と、機器の内部で自然に生まれるものがあります。内部雑音の代表が熱雑音で、抵抗の中の電子が温度によって不規則に揺れ動くことで発生します。温度がある限り絶対になくせない、通信の感度の根源的な限界です。「受信機の感度競争は熱雑音との戦い」と言ってよく、その大きさを見積もる式kTBは試験でも実務でも使う基本式です。

━━━━━━━━━━━━━━━━━━━━━━
🔑 雑音の分類
━━━━━━━━━━━━━━━━━━━━━━
・外部雑音：自然雑音（雷などの空電雑音、太陽・銀河からの宇宙雑音）と人工雑音（電動機の火花、自動車の点火、他システムからの干渉）★。
・内部雑音：機器内部で発生。
　熱雑音（サーマルノイズ）：抵抗体内の電子の熱運動による★。最も基本的。
　ショット雑音：半導体の接合を電荷が離散的に通過するゆらぎによる★。
　フリッカ雑音（1／f雑音）：低周波ほど大きくなる雑音。
・熱雑音は非常に広い周波数範囲で一様なスペクトルを持つため「白色雑音（ホワイトノイズ）」と呼ばれる★。
・振幅分布がガウス分布に従う白色雑音を加法性白色ガウス雑音（AWGN）といい、通信路の標準モデルとして使われる。

━━━━━━━━━━━━━━━━━━━━━━
🔑 熱雑音電力 kTB：最重要式
━━━━━━━━━━━━━━━━━━━━━━
・抵抗から取り出しうる熱雑音電力：N＝k×T×B★
　k：ボルツマン定数（1.38×10のマイナス23乗 J／K）
　T：絶対温度［K］（摂氏＋273）
　B：帯域幅［Hz］
・★雑音電力は「帯域幅に比例」する。帯域を2倍にすると雑音も2倍（3dB増）。→受信機の帯域は必要最小限に絞るのが感度向上の鉄則。
・常温（T＝290K）・帯域1Hzあたりの熱雑音電力は約マイナス174dBm★。この数値は暗記に値する。
・例題：常温で帯域1MHzの受信機の熱雑音電力
　式：N［dBm］＝−174＋10 log10（B）
　代入：−174＋10 log10（10の6乗）＝−174＋60
　答え：−114 dBm
・→受信信号がこの雑音レベルに対して十分大きくなければ復調できない。受信感度の理論的下限を与える。

━━━━━━━━━━━━━━━━━━━━━━
🔑 雑音指数（NF）：機器が雑音をどれだけ足すか
━━━━━━━━━━━━━━━━━━━━━━
・増幅器などを通ると、信号も雑音も増幅されるうえ、機器自身の内部雑音が加わる→SN比は必ず悪化する。
・雑音指数F＝入力SN比÷出力SN比★。dB表示ではNF＝入力SN比−出力SN比。
・理想（雑音を全く加えない）機器のNFは0dB。NFが小さいほど優秀★。
・例題：入力SN比40dB、出力SN比37dBの増幅器の雑音指数
　式：NF＝入力SN比−出力SN比
　代入：40−37
　答え：3 dB
・多段接続では初段のNFが支配的★（後段の雑音は初段の利得で割られて効きにくくなる）。→受信機の最前段（アンテナ直下）に低雑音増幅器（LNA）を置く理由。衛星放送アンテナのコンバータが皿の先端にあるのもこのため。

【図解】雑音のポイント
　項目｜式・値｜意味
　熱雑音電力｜N＝kTB｜帯域幅に比例
　1Hzあたり（常温）｜約−174 dBm｜感度の基準値
　雑音指数NF｜入力SN比−出力SN比（dB）｜小さいほど優秀
　多段接続｜初段のNFが支配的｜LNAを最前段に
　⚠ NFは「大きいほど高性能」ではない。0dBが理想で小さいほど良い

━━━━━━━━━━━━━━━━━━━━━━
🔑 頻出ひっかけと本試験での問われ方
━━━━━━━━━━━━━━━━━━━━━━
・×「熱雑音は帯域幅に関係なく一定」→○帯域幅に比例（N＝kTB）。
・×「熱雑音は温度を下げても減らない」→○絶対温度に比例するので冷やせば減る（低雑音受信機の冷却はこの応用）。
・×「雑音指数は大きいほど低雑音」→○小さいほど低雑音。
・×「多段増幅器の雑音指数は最終段で決まる」→○初段でほぼ決まる。
・kTBの計算（−174dBm＋10logB）、NFの引き算、白色雑音・AWGNの用語は繰り返し出題される。

━━━━━━━━━━━━━━━━━━━━━━
🔑 仕上げの一問一答
━━━━━━━━━━━━━━━━━━━━━━
・Q：熱雑音電力の式と比例関係は　→A：N＝kTB。絶対温度と帯域幅に比例
・Q：常温・帯域10MHzの熱雑音レベルは　→A：−174＋70＝−104dBm
・Q：入力SN比45dB・出力SN比42dBのNFは　→A：45−42＝3dB
・Q：多段増幅系のNFを支配するのは　→A：初段。だからアンテナ直下にLNAを置く
・Q：白色雑音の意味は　→A：広い周波数で電力密度が一様な雑音（熱雑音が代表）

★ここだけ暗記
・N＝kTB。帯域2倍で雑音3dB増。常温1Hzで−174dBm。
・熱雑音＝白色雑音＝ガウス分布（AWGNモデル）。
・NF＝入力SN比−出力SN比（dB）。0dBが理想。
・受信系は初段のNFが命→アンテナ直下にLNA。`,
