・ハミング距離：2つの符号語で異なるビットの数。符号全体の最小ハミング距離dが能力を決める★。
　検出できる誤り数＝d−1
　訂正できる誤り数＝（d−1）／2の整数部分
・例題：最小ハミング距離3の符号の検出・訂正能力
