・×「漏話減衰量が大きいほど漏話が大きい」→○小さい（良好）。
・×「周波数が低いほど漏話は大きくなる」→○高いほど大きい。
・×「より戻しを長く取るほど接続作業が確実になり特性も良い」→○特性は悪化。最小限にする。
・ツイストの目的（誘導の打ち消し）、UTPとSTPの違い、NEXTの定義は繰り返し出題。施工管理の実地でも「より戻し最小」「電力線との離隔」は記述ネタになる。

