        body: `▼ゼロから：光ファイバの中を光が進む経路のパターンを「モード」と呼びます。コアが太いファイバでは、まっすぐ進む光、大きくジグザグする光など多くの経路（マルチモード）が同時に存在します。経路の長さが違えば到着時刻もずれるので、パルスがなまってしまう。そこでコアを極限まで細く（約9μm）して経路を1本だけにしたのがシングルモードファイバです。長距離・大容量の基幹回線はすべてシングルモード、構内の短距離はマルチモードという住み分けの理由が、この節でわかります。

━━━━━━━━━━━━━━━━━━━━━━
🔑 マルチモードファイバ（MMF）
━━━━━━━━━━━━━━━━━━━━━━
・コア径が大きい（50μmまたは62.5μm）★ため、多数のモードが同時に伝搬する。
・ステップインデックス（SI）形：コアの屈折率が一様で、クラッドとの境界で階段状に変わる。経路差がそのまま到着時間差になり、モード分散が大きい×。
・グレーデッドインデックス（GI）形：コアの屈折率を中心が高く外側へなだらかに低くした分布★。外側を通る光ほど（屈折率が低い＝速度が速い）ため、遠回りでも速く走り、到着時刻の差が縮まる→モード分散を大幅に低減○。実用のMMFはGI形。
・コアが太い利点：光源（LEDなど）や他のファイバとの結合が容易、接続の位置ずれに寛容、コネクタ施工が楽○。
・用途：構内LAN・データセンター内などの短距離（数百m級）。

━━━━━━━━━━━━━━━━━━━━━━
🔑 シングルモードファイバ（SMF）
━━━━━━━━━━━━━━━━━━━━━━
・コア径を約9μmまで細くし、伝搬モードを基本モードの1つだけに制限★。
・モード分散が原理的に存在しない○→広帯域・長距離に圧倒的に有利。
・損失も低く（1.55μm帯で約0.2dB／km）、基幹伝送路・海底ケーブル・FTTHはすべてSMF★。
・欠点：コアが細いため、接続・結合に高い精度が必要（わずかな軸ずれが大きな損失になる）×。光源も発光面の小さいLD（半導体レーザ）が必要。
・カットオフ波長：これより長い波長でだけシングルモード動作する境目の波長。使用波長（1.31μm、1.55μm）はカットオフより長く設計されている。
・モードフィールド径：SMF内の光の実効的な広がり。接続損失の評価に使う。

━━━━━━━━━━━━━━━━━━━━━━
🔑 使い分けと規格の目安
━━━━━━━━━━━━━━━━━━━━━━
・距離と容量で選ぶ★：
　長距離・大容量（数km〜数千km）→SMF一択
　建物内・短距離（〜数百m）→MMF（結合・施工が容易で機器も安価）
・波長の使い分け：MMFは0.85μm帯が中心、SMFは1.31μm帯（ゼロ分散付近）と1.55μm帯（最低損失）★。
・見分け：ITU-T G.652（標準SMF）、OM3・OM4（レーザ最適化MMF）などの規格名で呼ばれる。
・例題：モード分散だけで帯域が決まるSI形MMFと、GI形MMF、SMFを帯域の広い順に並べよ
　考え方：モード分散の小ささの順
　答え：SMF＞GI形MMF＞SI形MMF★
・⚠「マルチモードの方がコアが細い」「シングルモードはLEDで駆動」といった逆の記述が定番の誤答肢。

【図解】SMFとMMFの比較
　項目｜シングルモード｜マルチモード
　コア径｜約9μm｜50または62.5μm
　モード分散｜なし｜あり（GI形で低減）
　距離・帯域｜長距離・広帯域｜短距離・中帯域
　接続性｜高精度が必要｜比較的容易
　⚠ コア径の数値（9と50）はそのまま出題される。取り違え注意

━━━━━━━━━━━━━━━━━━━━━━
🔑 頻出ひっかけと本試験での問われ方
━━━━━━━━━━━━━━━━━━━━━━
・×「シングルモードファイバのコア径はマルチモードより大きい」→○小さい（約9μm対50μm）。
・×「シングルモードファイバはモード分散が大きい」→○モード分散は原理的にない。
・×「GI形はSI形よりモード分散が大きい」→○小さい。屈折率分布で到着時刻をそろえている。
・×「長距離基幹系にはマルチモードが適する」→○シングルモード。
・コア径の数値、GI形の屈折率分布の狙い、波長帯（1.31／1.55μm）との組合せが繰り返し問われる。

━━━━━━━━━━━━━━━━━━━━━━
🔑 仕上げの一問一答
━━━━━━━━━━━━━━━━━━━━━━
・Q：SMFとMMFのコア径は　→A：SMF約9μm、MMF50または62.5μm
・Q：SMFにモード分散がない理由は　→A：伝搬モードが基本モード1つだけだから
・Q：GI形MMFの屈折率分布の狙いは　→A：外側ほど速く走らせ到着時刻をそろえる
・Q：長距離基幹系に使うのは　→A：SMF。構内短距離はMMF
・Q：SMFの使用波長2つは　→A：1.31μm（ゼロ分散付近）と1.55μm（最低損失）

★ここだけ暗記
・SMF＝コア9μm・モード分散なし・長距離大容量・接続はシビア。
・MMF＝コア50/62.5μm・結合容易・短距離用。実用はGI形。
・GI形＝中心の屈折率高いなだらか分布で到着時刻をそろえる。
・帯域：SMF＞GI＞SI。SMFの波長は1.31と1.55μm。`,
