        body: `▼ゼロから：どんなに透明なガラスでも、光は進むうちに少しずつ弱っていきます。光ファイバの損失は大きく3系統。ガラス自身が光を熱として吸い取る「吸収損失」、ガラスの分子レベルのゆらぎが光を四方八方にはね散らかす「散乱損失」、そして曲げたりつないだりする施工で生じる「曲げ損失・接続損失」です。石英ファイバの損失が最も小さくなる波長が1.55μmで、約0.2dB／km。この「最低損失波長1.55μm」は試験で何度も問われる黄金の数字です。

━━━━━━━━━━━━━━━━━━━━━━
🔑 ファイバ固有の損失：吸収と散乱
━━━━━━━━━━━━━━━━━━━━━━
・吸収損失：光のエネルギーが材料に吸われて熱になる。
　紫外吸収・赤外吸収：石英ガラス自身による原理的な吸収。
　不純物吸収：微量の金属イオンやOH基（水分）による吸収★。OH基は1.38μm付近に吸収のピークを作る（現在の低水分ファイバでは大幅に低減）。
・レイリー散乱損失★：ガラス内部の屈折率の微小なゆらぎ（密度ゆらぎ）による散乱。波長の4乗に反比例し、短波長ほど急激に大きくなる★。→短波長側の損失を支配する。空が青いのと同じ物理。
・構造不整損失：コア・クラッド境界の僅かな凹凸による散乱。
・損失の波長依存：0.85μm帯＞1.31μm帯＞1.55μm帯の順に小さくなり、1.55μm帯で最低の約0.2dB／km★。長波長側は赤外吸収で再び増える。

━━━━━━━━━━━━━━━━━━━━━━
🔑 曲げによる損失
━━━━━━━━━━━━━━━━━━━━━━
・マクロベンディング損失：ファイバを小さい半径で曲げると、全反射の条件が崩れて光がクラッド側へ漏れ出す★。曲げ半径が小さいほど急増。
・マイクロベンディング損失：ケーブル化や側圧でファイバ軸に微小なうねりが生じて起こる損失★。
・→施工では許容曲げ半径を守ることが絶対条件（余長処理・配線ルート設計に直結）。曲げに強い（漏れにくい屈折率設計の）曲げフリーファイバも宅内用に普及。
・⚠曲げ損失は施工起因であり、ファイバ材料の宿命であるレイリー散乱とは分類が違う。「損失の分類」を問う問題で混ぜてくる。

━━━━━━━━━━━━━━━━━━━━━━
🔑 接続損失：つなぎ目で失われる光
━━━━━━━━━━━━━━━━━━━━━━
・接続方法は3種類★：
　融着接続：ファイバ端面を放電で溶かして一体化。損失最小（0.1dB以下目安）で恒久接続の主流★。
　メカニカルスプライス：V溝で軸合わせし屈折率整合剤を挟んで機械固定。電源不要で簡便。
　コネクタ接続：着脱可能。損失はやや大きい（0.3〜0.5dB目安）★。
・接続損失の原因★：軸ずれ（コア中心のずれ）、角度ずれ、端面間隔（すき間）、端面の傷・汚れ、モードフィールド径の不一致。SMFはコアが細いため特にシビア。
・フレネル反射：端面とすき間（空気）の屈折率差による反射。屈折率整合剤や端面を斜め・球面研磨（APC・PC）で抑える★。
・測定：接続点ごとの損失や破断点は OTDR（光パルス試験器）で片端から測定できる★（後方散乱光の戻りを距離対損失のグラフで見る）。

【図解】光ファイバ損失の分類
　分類｜代表例｜特徴
　吸収損失｜不純物・OH基・赤外紫外｜熱になる
　散乱損失｜レイリー散乱｜波長の4乗に反比例
　曲げ損失｜マクロ・マイクロベンド｜施工起因
　接続損失｜軸ずれ・端面・すき間｜融着が最小
　⚠ 最低損失は1.55μm帯で約0.2dB／km。この数字は丸暗記

━━━━━━━━━━━━━━━━━━━━━━
🔑 頻出ひっかけと本試験での問われ方
━━━━━━━━━━━━━━━━━━━━━━
・×「レイリー散乱は波長が長いほど大きい」→○短いほど大きい（4乗に反比例）。
・×「石英ファイバの損失は0.85μm帯で最小」→○1.55μm帯で最小。
・×「コネクタ接続は融着接続より損失が小さい」→○融着が最小。
・×「OH基の吸収は損失に影響しない」→○1.38μm付近に吸収ピークを作る代表的不純物損失。
・損失の分類（吸収・散乱・曲げ・接続の仕分け）、融着とコネクタの損失比較、OTDRの用途は施工管理の実務問題としても出題される。

━━━━━━━━━━━━━━━━━━━━━━
🔑 仕上げの一問一答
━━━━━━━━━━━━━━━━━━━━━━
・Q：レイリー散乱の波長依存は　→A：波長の4乗に反比例。短波長ほど大きい
・Q：石英ファイバの最低損失波長と値は　→A：1.55μmで約0.2dB／km
・Q：OH基吸収のピーク波長は　→A：1.38μm付近
・Q：損失最小の接続方法は　→A：融着接続（0.1dB以下目安）
・Q：接続点の損失と位置を片端から測る計器は　→A：OTDR（光パルス試験器）

★ここだけ暗記
・レイリー散乱＝波長の4乗に反比例＝短波長ほど大。
・損失最小は1.55μm・約0.2dB／km。OH基吸収は1.38μm。
・接続損失：融着＜メカニカル＜コネクタ。原因は軸ずれ・端面・すき間。
・曲げ半径を守る。測定はOTDR。`,
