        emoji: '🔆',
        body: `▼ゼロから：光通信は「電気を光に変えて送り、光を電気に戻して受ける」往復の変換で成り立ちます。送る側の主役が半導体レーザ（LD）と発光ダイオード（LED）、受ける側がホトダイオード（PD）とアバランシホトダイオード（APD）です。LDは位相のそろった鋭い光を高速で出せるエリート、LEDは素朴で安価な働き者。受け側のAPDは、なだれ増倍という内部増幅機構を持つ高感度センサです。それぞれの得意分野と使い分けが、そのまま試験の出題ポイントになります。

━━━━━━━━━━━━━━━━━━━━━━
🔑 発光素子：LDとLED
━━━━━━━━━━━━━━━━━━━━━━
・LED（発光ダイオード）：pn接合に順方向電流を流し、電子と正孔の再結合で自然放出光を出す。
　特徴：安価・長寿命・駆動が簡単○。しかしスペクトル幅が広く、光の広がりも大きい×→高速・長距離に不向き。MMFと組み合わせた短距離用★。
・LD（半導体レーザ）：反転分布状態での誘導放出★を利用し、共振器（へき開面の鏡）で光を往復増幅してレーザ発振させる。
　特徴：スペクトル幅が狭い（単色性）・位相がそろう（可干渉性）・ビームが細い（指向性）・高出力・高速変調可能○★。SMFと組み合わせた中長距離・大容量の主役。
　しきい値電流：これを超えるとレーザ発振が始まる電流。温度で変動するため、自動出力制御（APC）や温度制御を行う★。
・DFBレーザ：回折格子を内蔵し単一波長で発振。スペクトル幅が極めて狭くWDM・長距離用○。
・変調方式：LDの電流を直接オンオフする直接変調と、LDは連続発振させ外部の光変調器で切る外部変調★。高速・長距離では波長チャーピングの少ない外部変調が有利。

━━━━━━━━━━━━━━━━━━━━━━
🔑 受光素子：PDとAPD
━━━━━━━━━━━━━━━━━━━━━━
・ホトダイオード（PD）：逆バイアスしたpn接合に光が入ると電子正孔対が生じ、光の強さに比例した電流が流れる★。
・PIN-PD：pとnの間に真性半導体（I層）を挟み、空乏層を広げて感度と応答速度を改善した実用標準★。増倍作用はない（1光子→1電子が上限）。
・APD（アバランシホトダイオード）：高い逆電圧をかけ、光で生じたキャリアを電界で加速して次々に衝突電離させる「なだれ（アバランシ）増倍」★で電流を内部増幅する。
　特徴：感度が高く長距離受信に有利○。ただし高電圧が必要で、増倍に伴う雑音（過剰雑音）があり、温度依存が大きい×。
・使い分け：短中距離・低コスト＝PIN-PD、長距離・高感度が必要＝APD★。
・受光感度：入射光電力に対する出力電流の比［A／W］。量子効率とともに受光素子の基本性能。

━━━━━━━━━━━━━━━━━━━━━━
🔑 光増幅器とその他の光部品
━━━━━━━━━━━━━━━━━━━━━━
・EDFA（エルビウム添加光ファイバ増幅器）★：エルビウムを添加したファイバに励起光を注入し、1.55μm帯の光を「光のまま」増幅する。電気に戻さないため超高速信号もWDMの多波長も一括増幅できる○。長距離・海底ケーブルの中継の主役。
・光カプラ：光を分岐・合流する受動部品。分岐すればその分レベルは下がる（2分岐で約3dB＋過剰損失）★。
・光アイソレータ：光を一方向のみ通す。反射戻り光がLDの発振を乱すのを防ぐ★。
・波長フィルタ・合分波器（AWGなど）：WDMの波長を束ね・分ける。
・光スイッチ・可変減衰器：経路切替やレベル調整に使う。

【図解】光デバイスの使い分け
　素子｜機能｜特徴
　LED｜電気→光（自然放出）｜安価・広スペクトル・短距離
　LD｜電気→光（誘導放出）｜単色・高速・長距離
　PIN-PD｜光→電気｜標準・増倍なし
　APD｜光→電気（内部増倍）｜高感度・高電圧・雑音増
　⚠ EDFAは光のまま増幅（電気変換なし）。「一度電気に戻す」は誤り

━━━━━━━━━━━━━━━━━━━━━━
🔑 頻出ひっかけと本試験での問われ方
━━━━━━━━━━━━━━━━━━━━━━
・×「LEDはLDよりスペクトル幅が狭い」→○広い。狭いのはLD（特にDFB）。
・×「LDは自然放出、LEDは誘導放出を利用」→○逆。LDが誘導放出＋共振器。
・×「APDには増倍作用がない」→○なだれ増倍がある。ないのはPIN-PD。
・×「EDFAは0.85μm帯の増幅に用いる」→○1.55μm帯。
・LDのしきい値電流と温度依存、PINとAPDの使い分け、光アイソレータの目的（戻り光防止）が選択肢の定番。発光・受光・増幅の機能対応表を確実に。

★ここだけ暗記
・LED＝自然放出・広スペクトル・短距離。LD＝誘導放出・単色・高速長距離。
・PIN-PD＝標準受光。APD＝なだれ増倍で高感度（高圧・雑音増）。
・EDFA＝1.55μm帯を光のまま一括増幅。
・アイソレータ＝一方通行で戻り光防止。分岐は2分岐で約3dB低下。`,
