        emoji: '💾',
        body: `▼ゼロから：コンピュータの記憶は一種類ではなく、速いが高くて小さいものから、遅いが安くて大きいものまで階段状に組み合わされています。CPUのすぐそばには超高速のレジスタとキャッシュ、作業机にあたる主記憶（RAM）、その外に倉庫であるSSDやハードディスク。よく使うものを手元に置き、たまにしか使わないものは倉庫へ。この「記憶階層」の考え方が、性能とコストの両立の知恵です。電源を切ると消えるか残るか（揮発性）、という区別も試験の定番です。

━━━━━━━━━━━━━━━━━━━━━━
🔑 半導体メモリの分類：RAMとROM
━━━━━━━━━━━━━━━━━━━━━━
・RAM（読み書き自由・揮発性＝電源断で消える）★：
　DRAM：コンデンサの電荷で記憶。集積度が高く安価で主記憶用★。電荷が漏れるため定期的なリフレッシュ（再書き込み）が必要★。
　SRAM：フリップフロップで記憶（順序回路の節の応用○）。高速でリフレッシュ不要だが高価・低集積→キャッシュメモリ用★。
・ROM（読み出し専用・不揮発性＝電源断でも残る）★：
　マスクROM：製造時に内容を焼き込み。変更不可。
　フラッシュメモリ：電気的に書き換え可能な不揮発メモリ★。USBメモリ・SSD・ファームウェア格納に使用。書き換え回数に上限がある。
・⚠「DRAMは不揮発」「フラッシュは揮発」といった揮発性の入れ替えが最頻出ひっかけ。

━━━━━━━━━━━━━━━━━━━━━━
🔑 記憶階層とキャッシュ
━━━━━━━━━━━━━━━━━━━━━━
・階層（速い・小さい→遅い・大きい）★：レジスタ→キャッシュ（SRAM）→主記憶（DRAM）→補助記憶（SSD・HDD）。
・キャッシュメモリ：CPUと主記憶の速度差を埋めるため、使用頻度の高いデータを置く小容量高速メモリ★。目的のデータがキャッシュにある確率をヒット率という。
・例題：キャッシュのアクセス時間10ns、主記憶100ns、ヒット率90％のときの平均アクセス時間
　式：平均＝ヒット率×キャッシュ時間＋（1−ヒット率）×主記憶時間
　代入：0.9×10＋0.1×100＝9＋10
　答え：19 ns
・局所性の原理：プログラムは直前に使った近くのデータを再び使う傾向がある。キャッシュが効く理由★。
・仮想記憶：主記憶より大きなメモリ空間を、補助記憶を併用して見せかける仕組み。不足分をページ単位で入れ替える（OSの節と関連）。

━━━━━━━━━━━━━━━━━━━━━━
🔑 補助記憶装置：SSDとHDD
━━━━━━━━━━━━━━━━━━━━━━
・HDD：磁気ディスクを回転させヘッドで読み書き。大容量・安価○だが、機械動作のため衝撃に弱く、アクセスに回転待ち・シーク時間がかかる×。
・SSD：フラッシュメモリの集合体。可動部がなく高速・耐衝撃・低消費電力○★。書き換え回数の上限と、容量単価がHDDより高い点が弱み。
・RAID★：複数ディスクを組み合わせ、速度や耐障害性を高める技術。
　RAID0（ストライピング）：分散書き込みで高速化。冗長性なし×。
　RAID1（ミラーリング）：同じ内容を2台に書く。1台壊れても継続○。容量効率は半分。
　RAID5：パリティを分散記録し、1台故障までデータ復元可能★。容量効率と耐障害性のバランス型。
　RAID6：二重パリティで2台故障まで耐える。
・バックアップの原則：RAIDは故障対策であり、誤消去・災害・ランサムウェア対策のバックアップの代わりにはならない★。

【図解】主な記憶素子の対比
　素子｜揮発性｜用途
　DRAM｜揮発（要リフレッシュ）｜主記憶
　SRAM｜揮発（リフレッシュ不要）｜キャッシュ
　フラッシュ｜不揮発｜SSD・USB・ファーム
　HDD｜不揮発｜大容量補助記憶
　⚠ DRAM＝リフレッシュ必要、SRAM＝不要。逆にした選択肢が定番

━━━━━━━━━━━━━━━━━━━━━━
🔑 頻出ひっかけと本試験での問われ方
━━━━━━━━━━━━━━━━━━━━━━
・×「SRAMはリフレッシュが必要」→○不要。必要なのはDRAM。
・×「キャッシュメモリにはDRAMが使われる」→○SRAM。DRAMは主記憶。
・×「フラッシュメモリは電源を切ると内容が消える」→○不揮発で残る。
・×「RAID1は高速化のための分散書き込み」→○それはRAID0。RAID1はミラーリング。
・平均アクセス時間の計算（ヒット率の重み付き平均）、RAIDレベルの対応、記憶階層の並べ替えが問われる。

★ここだけ暗記
・DRAM＝主記憶・要リフレッシュ。SRAM＝キャッシュ・FF記憶。
・フラッシュ＝不揮発・書換上限あり。SSD＝無可動・高速・耐衝撃。
・平均アクセス＝h×速い＋（1−h）×遅い。
・RAID0高速化・RAID1ミラー・RAID5パリティ分散（1台故障OK）。`,
