・×「ゼロデイ攻撃はパッチ適用で確実に防げる」→○パッチ提供前の攻撃なので防げない。多層防御で局限。
・×「DDoSは単一の発信元から行われる」→○多数の踏み台から分散して行われる。
・攻撃名と手口・対策の三択対応、マルウェア3分類、CSIRTの役割、初動対応（隔離と証拠保全）が定番の出題。

★ここだけ暗記
・マルウェア3分類：ウイルス（寄生）・ワーム（自己増殖）・トロイ（偽装潜伏）。
